  "leaf.gradcam": { en: "🔍 Explainable AI – Grad-CAM Heatmap", hi: "🔍 व्याख्या योग्य AI – ग्रैड-कैम हीटमैप", gu: "🔍 સમજાવી શકાય તેવું AI – Grad-CAM હીટમેપ", mr: "🔍 स्पष्टीकरणीय AI – Grad-CAM हीटमॅप", ta: "🔍 விளக்கக்கூடிய AI – Grad-CAM வெப்ப வரைபடம்" },
  "leaf.heatmap": { en: "Heatmap Visualization", hi: "हीटमैप विज़ुअलाइज़ेशन", gu: "હીટમેપ વિઝ્યુઅલાઇઝેશન", mr: "हीटमॅप व्हिज्युअलायझेशन", ta: "வெப்ப வரைபடக் காட்சிப்படுத்தல்" },
  "leaf.heatmapDesc": { en: "Affected region highlighted using Gradient-weighted Class Activation Mapping", hi: "ग्रेडिएंट-वेटेड क्लास एक्टिवेशन मैपिंग का उपयोग करके प्रभावित क्षेत्र को हाइलाइट किया गया", gu: "ગ્રેડિયન્ટ-વેટેડ ક્લાસ એક્ટિવેશન મેપિંગનો ઉપયોગ કરીને અસરગ્રસ્ત વિસ્તાર હાઇલાઇટ કરાયો", mr: "ग्रेडियंट-वेटेड क्लास ॲक्टिव्हेशन मॅपिंग वापरून प्रभावित क्षेत्र हायलाइट केले", ta: "கிரேடியன்ட்-வெயிட்டட் கிளாஸ் ஆக்டிவேஷன் மேப்பிங் மூலம் பாதிக்கப்பட்ட பகுதி சிறப்பிக்கப்பட்டுள்ளது" },
  "leaf.preventive": { en: "🛡️ Preventive Advisory", hi: "🛡️ निवारक सलाह", gu: "🛡️ નિવારક સલાહ", mr: "🛡️ प्रतिबंधात्मक सल्ला", ta: "🛡️ தடுப்பு ஆலோசனை" },
  "leaf.prev1": { en: "Apply seasonal preventive fungicide spray before monsoon onset.", hi: "मानसून शुरू होने से पहले मौसमी निवारक फफूंदनाशक छिड़काव करें।", gu: "ચોમાસા પહેલા મોસમી નિવારક ફૂગનાશક છંટકાવ કરો.", mr: "मान्सूनपूर्वी हंगामी प्रतिबंधात्मक बुरशीनाशक फवारणी करा.", ta: "பருவமழை தொடங்குவதற்கு முன் பருவகால தடுப்பு பூஞ்சைக்கொல்லி தெளிப்பு செய்யவும்." },
  "leaf.prev2": { en: "Ensure balanced fertilizer application (NPK ratio as per soil test).", hi: "संतुलित उर्वरक उपयोग सुनिश्चित करें (मिट्टी परीक्षण के अनुसार NPK अनुपात)।", gu: "સંતુલિત ખાતર ઉપયોગ સુનિશ્ચિત કરો (માટી પરીક્ષણ મુજબ NPK પ્રમાણ).", mr: "संतुलित खत वापर सुनिश्चित करा (माती चाचणीनुसार NPK प्रमाण).", ta: "சமச்சீர் உர பயன்பாட்டை உறுதிசெய்யவும் (மண் பரிசோதனையின்படி NPK விகிதம்)." },
  "leaf.prev3": { en: "Monitor pest activity weekly — use yellow sticky traps.", hi: "साप्ताहिक कीट गतिविधि की निगरानी करें — पीले चिपचिपे जाल का उपयोग करें।", gu: "સાપ્તાહિક જીવાત પ્રવૃત્તિનું નિરીક્ષણ કરો — પીળા ચીકણા ફાંસાનો ઉપયોગ કરો.", mr: "साप्ताहिक कीटक क्रियाकलापांचे निरीक्षण करा — पिवळे चिकट सापळे वापरा.", ta: "வாராந்திர பூச்சி நடவடிக்கையை கண்காணிக்கவும் — மஞ்சள் ஒட்டும் பொறிகளைப் பயன்படுத்தவும்." },
  "leaf.prev4": { en: "Continue regular irrigation and apply compost monthly.", hi: "नियमित सिंचाई जारी रखें और मासिक खाद डालें।", gu: "નિયમિત સિંચાઈ ચાલુ રાખો અને માસિક ખાતર નાખો.", mr: "नियमित सिंचन सुरू ठेवा आणि मासिक कंपोस्ट खत द्या.", ta: "வழக்கமான பாசனத்தை தொடரவும், மாதாந்திர உரம் இடவும்." },
  "leaf.downloadPdf": { en: "Download PDF Report", hi: "PDF रिपोर्ट डाउनलोड करें", gu: "PDF અહેવાલ ડાઉનલોડ કરો", mr: "PDF अहवाल डाउनलोड करा", ta: "PDF அறிக்கை பதிவிறக்கம்" },
  "leaf.voiceAdvisory": { en: "Listen Voice Advisory", hi: "वॉइस सलाह सुनें", gu: "વૉઇસ સલાહ સાંભળો", mr: "व्हॉइस सल्ला ऐका", ta: "குரல் ஆலோசனை கேளுங்கள்" },
  "leaf.stopVoice": { en: "Stop Voice", hi: "आवाज़ बंद करें", gu: "અવાજ બંધ કરો", mr: "आवाज थांबवा", ta: "குரலை நிறுத்து" },
