  // Video Crop Scan
  "video.title": { en: "Video Crop Scan", hi: "वीडियो फसल स्कैन", gu: "વીડિયો પાક સ્કેન", mr: "व्हिडिओ पीक स्कॅन", ta: "வீடியோ பயிர் ஸ்கேன்" },
  "video.subtitle": { en: "Upload a crop video for multi-frame AI analysis and comprehensive diagnosis.", hi: "बहु-फ्रेम AI विश्लेषण और व्यापक निदान के लिए फसल का वीडियो अपलोड करें।", gu: "મલ્ટિ-ફ્રેમ AI વિશ્લેષણ અને વ્યાપક નિદાન માટે પાકનો વીડિયો અપલોડ કરો.", mr: "मल्टी-फ्रेम AI विश्लेषण आणि सर्वसमावेशक निदानासाठी पिकाचा व्हिडिओ अपलोड करा.", ta: "பல-பிரேம் AI பகுப்பாய்வு மற்றும் விரிவான கண்டறிதலுக்கு பயிர் வீடியோவை பதிவேற்றுக." },
  "video.uploadTitle": { en: "📹 Upload Crop Video", hi: "📹 फसल का वीडियो अपलोड करें", gu: "📹 પાકનો વીડિયો અપલોડ કરો", mr: "📹 पिकाचा व्हिडिओ अपलोड करा", ta: "📹 பயிர் வீடியோவை பதிவேற்றுக" },
  "video.uploadText": { en: "Click to upload video file", hi: "वीडियो फ़ाइल अपलोड करने के लिए क्लिक करें", gu: "વીડિયો ફાઇલ અપલોડ કરવા ક્લિક કરો", mr: "व्हिडिओ फाइल अपलोड करण्यासाठी क्लिक करा", ta: "வீடியோ கோப்பை பதிவேற்ற கிளிக் செய்யவும்" },
