  "video.extractedFrames": { en: "🖼️ Extracted Frames", hi: "🖼️ निकाले गए फ्रेम", gu: "🖼️ નિકાળેલા ફ્રેમ", mr: "🖼️ काढलेले फ्रेम", ta: "🖼️ பிரித்தெடுக்கப்பட்ட பிரேம்கள்" },
