  "mandi.title": { en: "Mandi Price Dashboard", hi: "मंडी भाव डैशबोर्ड", gu: "મંડી ભાવ ડેશબોર્ડ", mr: "बाजारभाव डॅशबोर्ड", ta: "சந்தை விலை டாஷ்போர்டு" },
  "mandi.subtitle": { en: "Latest market prices from official Agricultural Produce Market Committee (APMC) sources.", hi: "आधिकारिक कृषि उपज मंडी समिति (APMC) स्रोतों से नवीनतम बाजार भाव।", gu: "સત્તાવાર કૃષિ ઉત્પાદન બજાર સમિતિ (APMC) સ્ત્રોતોમાંથી નવીનતમ બજાર ભાવ.", mr: "अधिकृत कृषी उत्पन्न बाजार समिती (APMC) स्रोतांकडून नवीनतम बाजारभाव.", ta: "அதிகாரப்பூர்வ வேளாண் உற்பத்தி சந்தைக் குழு (APMC) மூலங்களிலிருந்து சமீபத்திய சந்தை விலைகள்." },
