  "mandi.footer": { en: "📌 Prices updated daily from official APMC mandi sources. Last updated: 19 Feb 2026, 06:00 AM IST.", hi: "📌 आधिकारिक APMC मंडी स्रोतों से दैनिक अपडेट। अंतिम अपडेट: 19 फरवरी 2026, सुबह 06:00 IST।", gu: "📌 સત્તાવાર APMC મંડી સ્ત્રોતોમાંથી દૈનિક અપડેટ. છેલ્લું અપડેટ: 19 ફેબ્રુઆરી 2026, સવારે 06:00 IST.", mr: "📌 अधिकृत APMC बाजार स्रोतांकडून दैनिक अपडेट. शेवटचे अपडेट: 19 फेब्रुवारी 2026, सकाळी 06:00 IST.", ta: "📌 அதிகாரப்பூர்வ APMC சந்தை மூலங்களிலிருந்து தினசரி புதுப்பிப்பு. கடைசி புதுப்பிப்பு: 19 பிப் 2026, காலை 06:00 IST." },

  // Weather
  "weather.title": { en: "Weather Risk Advisory", hi: "मौसम जोखिम सलाह", gu: "હવામાન જોખમ સલાહ", mr: "हवामान धोका सल्ला", ta: "வானிலை அபாய ஆலோசனை" },
  "weather.subtitle": { en: "Weather-based crop risk assessment and preventive advisories for your region.", hi: "आपके क्षेत्र के लिए मौसम-आधारित फसल जोखिम मूल्यांकन और निवारक सलाह।", gu: "તમારા વિસ્તાર માટે હવામાન-આધારિત પાક જોખમ મૂલ્યાંકન અને નિવારક સલાહ.", mr: "तुमच्या प्रदेशासाठी हवामान-आधारित पीक धोका मूल्यांकन आणि प्रतिबंधात्मक सल्ला.", ta: "உங்கள் பகுதிக்கான வானிலை அடிப்படையிலான பயிர் அபாய மதிப்பீடு மற்றும் தடுப்பு ஆலோசனைகள்." },
  "weather.location": { en: "📍 Your Location", hi: "📍 आपका स्थान", gu: "📍 તમારું સ્થાન", mr: "📍 तुमचे स्थान", ta: "📍 உங்கள் இருப்பிடம்" },
  "weather.locationPlaceholder": { en: "Enter district or PIN code", hi: "जिला या पिन कोड दर्ज करें", gu: "જિલ્લો અથવા પિન કોડ દાખલ કરો", mr: "जिल्हा किंवा पिन कोड टाका", ta: "மாவட்டம் அல்லது பின் குறியீட்டை உள்ளிடவும்" },
